def get_config():
    config = {
        "version": "1.0",
        "environment": "production",
        "debug_mode": False,
        "timeout_seconds": 30,
        "max_retries": 3,
        "features": {
            "caching": True,
            "compression": True,
            "logging": True
        },
        "database": {
            "host": "localhost",
            "port": 5432,
            "name": "app_db"
        }
    }
    return json.dumps(config, indent=2)

if __name__ == "__main__":
    server.run()
